import { muted } from "../../ui/index.js";
import { isCiEnv, isDenoTestingEnv } from "../../../src/config/index.js";
import { isInteractive as checkIsInteractive } from "../../../src/platform/index.js";
import { isInteractive as isCliInteractive } from "../../shared/interactive.js";
import { validateProjectName } from "../../shared/project-name.js";
import { select, textInput } from "../../utils/terminal-select.js";
import { DEFAULT_TEMPLATE, getTemplateSelectOptions } from "./catalog.js";
export { validateProjectName };
function canRunWizard() {
    return isCliInteractive() && !(isCiEnv() || isDenoTestingEnv()) && checkIsInteractive();
}
export function formatWizardIntro() {
    return `\n${SETUP_COPY.intro}`;
}
export const SETUP_COPY = {
    intro: "Let's set up your project.",
    location: "Create project in:",
    template: "Choose a starter template:",
    runtime: "Select runtime:",
    git: "Initialize Git?",
};
const SETUP_PROMPT_DISPLAY = {
    showMarker: false,
    showInstructions: false,
    showDescriptions: false,
};
export async function runInteractiveWizard(existingName, presetRuntime) {
    if (!canRunWizard()) {
        return {
            projectName: existingName ?? null,
            template: DEFAULT_TEMPLATE,
            runtime: presetRuntime ?? "node",
            initGit: false,
            skipped: true,
            cancelled: false,
        };
    }
    console.log(formatWizardIntro());
    let projectName = existingName ?? null;
    // Location prompt (skip when name was provided via CLI)
    if (!existingName) {
        const locationChoice = await select(SETUP_COPY.location, [
            {
                value: "current",
                label: "Current directory",
                description: "Use this directory",
            },
            {
                value: "new",
                label: "New directory",
                description: "Create a new directory",
            },
        ], 0, SETUP_PROMPT_DISPLAY);
        if (locationChoice === null) {
            console.log();
            console.log(muted("  Cancelled."));
            console.log();
            return {
                projectName: null,
                template: DEFAULT_TEMPLATE,
                runtime: "node",
                initGit: false,
                skipped: false,
                cancelled: true,
            };
        }
        if (locationChoice === "new") {
            const name = await textInput("Project name", "my-app", SETUP_PROMPT_DISPLAY);
            if (name === null) {
                console.log();
                console.log(muted("  Cancelled."));
                console.log();
                return {
                    projectName: null,
                    template: DEFAULT_TEMPLATE,
                    runtime: "node",
                    initGit: false,
                    skipped: false,
                    cancelled: true,
                };
            }
            const validName = name || "my-app";
            const nameError = validateProjectName(validName);
            if (nameError) {
                console.log(muted(`\n  ${nameError}\n`));
                return {
                    projectName: null,
                    template: DEFAULT_TEMPLATE,
                    runtime: "node",
                    initGit: false,
                    skipped: false,
                    cancelled: true,
                };
            }
            projectName = validName;
        }
    }
    // Template selection
    const templateChoice = await select(SETUP_COPY.template, getTemplateSelectOptions(), 0, SETUP_PROMPT_DISPLAY);
    if (templateChoice === null) {
        console.log();
        console.log(muted("  Cancelled."));
        console.log();
        return {
            projectName: null,
            template: DEFAULT_TEMPLATE,
            runtime: "node",
            initGit: false,
            skipped: false,
            cancelled: true,
        };
    }
    const template = templateChoice;
    // Runtime selection (skipped when CLI passed --runtime explicitly)
    let runtime = presetRuntime ?? "node";
    if (presetRuntime === undefined) {
        const runtimeChoice = await select(SETUP_COPY.runtime, [
            { value: "node", label: "Node.js", description: "Default" },
            { value: "bun", label: "Bun", description: "Fast JS runtime" },
            { value: "deno", label: "Deno", description: "Secure-by-default" },
        ], 0, SETUP_PROMPT_DISPLAY);
        if (runtimeChoice === null) {
            console.log();
            console.log(muted("  Cancelled."));
            console.log();
            return {
                projectName: null,
                template: DEFAULT_TEMPLATE,
                runtime: "node",
                initGit: false,
                skipped: false,
                cancelled: true,
            };
        }
        runtime = runtimeChoice;
    }
    // Git init prompt
    const gitChoice = await select(SETUP_COPY.git, [
        { value: "yes", label: "Yes", description: "Initialize git and create first commit" },
        { value: "no", label: "No", description: "Skip git initialization" },
    ], 0, SETUP_PROMPT_DISPLAY);
    if (gitChoice === null) {
        console.log();
        console.log(muted("  Cancelled."));
        console.log();
        return {
            projectName: null,
            template: DEFAULT_TEMPLATE,
            runtime: "node",
            initGit: false,
            skipped: false,
            cancelled: true,
        };
    }
    const initGit = gitChoice === "yes";
    return {
        projectName,
        template,
        runtime,
        initGit,
        skipped: false,
        cancelled: false,
    };
}
export function shouldRunWizard(options) {
    // Always run wizard unless template is explicitly specified via --template
    return !options.template;
}
